const subject = $json.Subject || '';
const parts = subject.trim().split(/\s+/);

let action;
let taskId;
let update;

if (parts[0]?.toUpperCase() === 'NEEDS' && parts[1]?.toUpperCase() === 'HELP') {
  action = 'NEEDS HELP';
  taskId = parts[2];
  update = parts.slice(3).join(' ');
} else {
  action = parts[0]?.toUpperCase();
  taskId = parts[1];
  update = parts.slice(2).join(' ');
}

return [{
  json: {
    messageId: $json.id,
    employeeEmail: $json.From,
    action,
    taskId,
    update
  }
}];

const tasks = $input.all();

const totalTasks = tasks.length;

const completedTasks = tasks.filter(
  item => item.json.fields.Status === 'Completed'
).length;

const progress = totalTasks > 0
  ? Math.round((completedTasks / totalTasks) * 100)
  : 0;

return [{
  json: {
    projectId: tasks[0]?.json.fields["Project ID"],
    totalTasks,
    completedTasks,
    progress
  }
}];

const totalTasks = $json.totalTasks;
const completedTasks = $json.completedTasks;
const progress = $json.progress;

let status = 'In Progress';

if (completedTasks === 0) {
  status = 'Scheduled';
}

if (totalTasks > 0 && completedTasks === totalTasks) {
  status = 'Completed';
}

return [{
  json: {
    ...$json,
    status
  }
}];
